import { InfrastructureItem } from '@/types/globe';

export const INFRASTRUCTURE: InfrastructureItem[] = [
  // ===== AIRPORTS =====
  { id: 'apt-atl', name: 'Hartsfield-Jackson Atlanta', type: 'airport', category: 'transport', latitude: 33.6407, longitude: -84.4277, country: 'United States', description: "Hartsfield-Jackson Atlanta International Airport has held the title of the world's busiest airport by passenger traffic for over two decades. Originally built in the 1920s as Candler Field, it was renamed in honor of former mayors William B. Hartsfield and Maynard Jackson. The airport serves as the primary hub for Delta Air Lines and handles over 90 million passengers annually.\n\nStrategically, Hartsfield-Jackson is a critical node in the U.S. domestic and international aviation network, with five parallel runways and two terminal complexes containing nearly 200 gates. Its location in the southeastern United States makes it a natural connecting point for flights between the Americas, Europe, and Africa. The airport generates over $80 billion in annual economic impact for the Atlanta metropolitan region and employs more than 63,000 people directly.\n\nRecent developments include a $6 billion capital improvement program featuring a new concourse, elevated train system, and expanded international terminal. The airport has also implemented advanced biometric screening and sustainable energy initiatives including one of the largest airport solar farms in the country." },
  { id: 'apt-dxb', name: 'Dubai International', type: 'airport', category: 'transport', latitude: 25.2532, longitude: 55.3657, country: 'UAE', description: "Dubai International Airport is the primary aviation hub of the United Arab Emirates and one of the busiest airports globally for international passenger traffic. Established in 1960 with a single runway, it has undergone massive expansion to become a symbol of Dubai's transformation into a global business and tourism center.\n\nThe airport serves as the main hub for Emirates airline and budget carrier flydubai, connecting over 260 destinations across six continents. Its geographic position between Europe, Africa, and Asia makes it an ideal long-haul connecting point, with over 89 million passengers passing through annually. The airport features three terminals, including the world's largest building by floor space (Terminal 3).\n\nDubai International plays a critical role in the UAE's economic diversification strategy, contributing over 27% of Dubai's GDP. The airport has pioneered smart travel technologies including biometric corridors and AI-powered customs processing. Plans are underway to eventually transition primary operations to the newer Al Maktoum International Airport (DWC), which will have capacity for 260 million passengers annually." },
  { id: 'apt-lhr', name: 'London Heathrow', type: 'airport', category: 'transport', latitude: 51.4700, longitude: -0.4543, country: 'United Kingdom', description: "London Heathrow is the United Kingdom's largest and busiest airport, serving as a major international aviation hub since its establishment on the site of a former RAF airfield in 1946. Located in west London, it is the primary hub for British Airways and Virgin Atlantic, handling approximately 80 million passengers per year across four operational terminals.\n\nHeathrow's strategic importance extends beyond aviation—it is a critical gateway for UK trade, handling more cargo by value than all other UK airports combined. The airport connects to over 200 destinations and serves as the primary transatlantic corridor between Europe and North America. Terminal 5, opened in 2008, is considered one of the world's finest airport terminals.\n\nThe controversial third runway expansion, debated for decades, remains one of the UK's most significant infrastructure decisions. Heathrow has committed to net-zero carbon emissions by 2050 and has invested heavily in sustainable aviation fuel research, electric ground vehicles, and noise reduction technologies for surrounding communities." },
  { id: 'apt-hnd', name: 'Tokyo Haneda', type: 'airport', category: 'transport', latitude: 35.5494, longitude: 139.7798, country: 'Japan', description: "Tokyo Haneda Airport, officially Tokyo International Airport, is Japan's busiest airport and one of the most efficient in the world. Originally opened in 1931, it served as Tokyo's sole commercial airport until Narita International Airport opened in 1978 for international flights. Since 2010, Haneda has progressively reclaimed international routes, particularly with the opening of its fourth runway and international terminal.\n\nLocated just 14 kilometers from central Tokyo, Haneda offers unmatched convenience for business and leisure travelers. The airport handles over 85 million passengers annually and consistently ranks among the world's cleanest and most punctual airports. It serves as a hub for Japan Airlines and All Nippon Airways.\n\nHaneda's engineering is remarkable—its fourth runway was built on reclaimed land in Tokyo Bay, and the airport operates under strict noise regulations that historically limited nighttime flights. Recent expansions have increased international capacity, and the airport played a central role during the 2020 Tokyo Olympics. Advanced robotics, multilingual AI assistants, and automated baggage systems make Haneda a showcase for Japanese technological innovation." },
  { id: 'apt-cdg', name: 'Paris Charles de Gaulle', type: 'airport', category: 'transport', latitude: 49.0097, longitude: 2.5479, country: 'France', description: "Paris Charles de Gaulle Airport, named after the French president and wartime leader, is France's largest international airport and one of Europe's busiest aviation hubs. Opened in 1974 to relieve congestion at Orly Airport, CDG has grown into a sprawling complex with three terminal buildings, four runways, and capacity for over 80 million passengers annually.\n\nThe airport serves as the primary hub for Air France-KLM and is a major Skyteam alliance connecting point. Its architectural centerpiece, Terminal 1, was revolutionary at opening with its circular design and tube-like satellite gates. Terminal 2, subsequently expanded multiple times, handles the bulk of traffic. CDG's location northeast of Paris connects to the city via RER train, high-speed TGV rail, and extensive highway networks.\n\nCDG is a critical European cargo hub, handling over 2 million tonnes of freight annually. The airport has faced challenges including the 2004 Terminal 2E roof collapse and ongoing debate about a potential fifth terminal. Recent investments focus on sustainable operations, with France banning short-haul domestic flights where rail alternatives exist under 2.5 hours." },
  { id: 'apt-ord', name: "Chicago O'Hare", type: 'airport', category: 'transport', latitude: 41.9742, longitude: -87.9073, country: 'United States', description: "Chicago O'Hare International Airport is one of the world's busiest airports and a critical hub for domestic and international aviation in the United States. Originally developed as a military airfield during World War II (Orchard Place Airport, giving it the ORD code), it was converted to civilian use and renamed in 1949 after Lieutenant Commander Edward 'Butch' O'Hare, a Medal of Honor recipient.\n\nO'Hare serves as a primary hub for United Airlines and American Airlines, offering connections to over 200 domestic and international destinations. Its central U.S. location makes it a natural connecting point for coast-to-coast and transatlantic flights. The airport handles approximately 83 million passengers annually across four terminal buildings.\n\nA massive $8.5 billion O'Hare 21 modernization program is currently underway, the largest capital program in the airport's history. This includes a complete rebuild of Terminal 2, a new global terminal, expanded runways, and an automated people mover system. O'Hare's economic impact on the Chicago metropolitan area exceeds $45 billion annually." },
  { id: 'apt-pek', name: 'Beijing Capital', type: 'airport', category: 'transport', latitude: 40.0799, longitude: 116.6031, country: 'China', description: "Beijing Capital International Airport was China's primary aviation gateway for decades and remains one of the world's busiest airports despite the opening of Beijing Daxing International Airport in 2019. Originally built in 1958 as one of China's first major airports, it has been expanded multiple times, most notably with the addition of the Norman Foster-designed Terminal 3 for the 2008 Beijing Olympics.\n\nTerminal 3, at the time of completion the world's largest airport building, features a dramatic roof inspired by a Chinese dragon and spans over 1.3 million square meters. The airport serves as a hub for Air China and several other Star Alliance carriers, handling approximately 100 million passengers annually at peak.\n\nBeijing Capital's strategic importance extends to national security and political significance as the primary airport serving China's capital. Its proximity to major government and military installations makes it a sensitive facility. With the opening of Daxing, Beijing became one of few cities operating two massive international airports, with traffic distributed between them based on airline alliance membership." },
  { id: 'apt-sin', name: 'Singapore Changi', type: 'airport', category: 'transport', latitude: 1.3644, longitude: 103.9915, country: 'Singapore', description: "Singapore Changi Airport is consistently ranked among the world's best airports, known for its exceptional passenger experience, efficiency, and innovative design. Opened in 1981, it replaced the former Paya Lebar Airport and has since grown to four terminals plus the spectacular Jewel Changi complex.\n\nChangi serves as a critical aviation hub in Southeast Asia, connecting Oceania with Asia, Europe, and the Middle East. It is the primary hub for Singapore Airlines and Scoot, handling over 68 million passengers annually. The airport's geographic position at the crossroads of major air routes makes it one of the most connected airports globally.\n\nThe Jewel Changi development, opened in 2019, features the world's tallest indoor waterfall (the Rain Vortex), a five-story garden, and extensive retail. Terminal 5, currently under construction, will be the airport's largest terminal and include advanced automated systems. Changi's economic contribution to Singapore is immense, supporting the city-state's position as a global trade, finance, and tourism hub." },
  { id: 'apt-ist', name: 'Istanbul Airport', type: 'airport', category: 'transport', latitude: 41.2753, longitude: 28.7519, country: 'Turkey', description: "Istanbul Airport is Turkey's primary international gateway and one of the world's newest mega-airports, replacing the historic Atatürk Airport in 2019. Built on the European side of Istanbul near the Black Sea coast, the airport represents one of the largest infrastructure projects in Turkish history, with an ultimate planned capacity of 200 million passengers annually across six runways.\n\nThe airport serves as the main hub for Turkish Airlines, which has leveraged Istanbul's unique geographic position bridging Europe and Asia to build one of the world's largest route networks. The airport currently handles over 90 million passengers and connects to more than 300 destinations worldwide.\n\nIstanbul Airport's architecture reflects Turkish design elements with its tulip-shaped control tower and vast terminal featuring natural light and traditional motifs. The facility includes advanced baggage handling, biometric processing, and energy-efficient design. Its strategic importance extends beyond aviation—Turkey views the airport as central to its ambition to become a global aviation and logistics hub connecting three continents." },
  { id: 'apt-icn', name: 'Incheon International', type: 'airport', category: 'transport', latitude: 37.4602, longitude: 126.4407, country: 'South Korea', description: "Incheon International Airport, located on Yeongjong Island west of Seoul, is South Korea's largest airport and a consistently top-ranked facility globally. Opened in 2001 to replace the aging Gimpo International Airport for international flights, Incheon was built on reclaimed land and represents one of South Korea's most ambitious infrastructure projects.\n\nThe airport serves as the primary hub for Korean Air and Asiana Airlines, handling approximately 72 million passengers annually across two terminal buildings. Its geographic position makes it an ideal transit point between North America and Asia, with Korean Air operating one of the most extensive transpacific networks.\n\nIncheon is renowned for its cultural attractions, including a Korean Cultural Museum, traditional craft workshops, and an ice skating rink within the terminal. The airport's efficiency is legendary, with average immigration processing times under 12 minutes and baggage delivery under 13 minutes. A third terminal phase is planned to increase capacity to 100 million passengers. Incheon also serves as a key military logistics point given its proximity to the Korean Demilitarized Zone." },
  { id: 'apt-fra', name: 'Frankfurt Airport', type: 'airport', category: 'transport', latitude: 50.0379, longitude: 8.5622, country: 'Germany', description: "Frankfurt Airport is Germany's busiest airport and a critical European aviation hub, serving as the primary base for Lufthansa German Airlines. Established in 1936, the airport has grown through continuous expansion to handle over 70 million passengers annually, making it the fourth-busiest airport in Europe.\n\nFrankfurt's central location in Europe and excellent ground transportation connections—including a dedicated long-distance railway station with ICE high-speed train service—make it one of the continent's premier connecting hubs. The airport is a major Star Alliance gateway, connecting hundreds of European cities with intercontinental destinations.\n\nThe airport is also Europe's largest cargo hub by weight, handling over 2 million tonnes annually, reflecting Frankfurt's role as a global financial center and logistics corridor. Recent developments include Terminal 3, a major expansion project adding capacity for 25 million additional passengers. Frankfurt Airport is also home to significant aircraft maintenance operations and serves as a strategic NATO logistics hub." },
  { id: 'apt-syd', name: 'Sydney Kingsford Smith', type: 'airport', category: 'transport', latitude: -33.9461, longitude: 151.1772, country: 'Australia', description: "Sydney Kingsford Smith Airport is Australia's busiest and oldest commercial airport, named after pioneering aviator Sir Charles Kingsford Smith who made the first transpacific flight in 1928. Located in the suburb of Mascot, just 8 kilometers from the Sydney CBD, the airport has served as Australia's primary international gateway since its establishment in the 1920s.\n\nThe airport handles over 44 million passengers annually across three terminals and serves as the main hub for Qantas Airways. Its strategic importance as the primary link between Australia and the rest of the world cannot be overstated—virtually all of the country's international diplomatic, business, and tourism traffic passes through Sydney.\n\nA long-running capacity constraint due to a government-imposed cap of 80 movements per hour has led to the development of Western Sydney International Airport at Badgerys Creek, expected to open in 2026. Sydney Airport operates under strict curfew hours (11 PM to 6 AM) due to residential proximity, a policy that has shaped Australian aviation scheduling for decades." },
  { id: 'apt-gru', name: 'São Paulo Guarulhos', type: 'airport', category: 'transport', latitude: -23.4356, longitude: -46.4731, country: 'Brazil', description: "São Paulo/Guarulhos International Airport is South America's busiest airport and Brazil's primary international aviation gateway. Named after Governor André Franco Montoro, the airport opened in 1985 to relieve congestion at Congonhas Airport and has grown to handle over 40 million passengers annually.\n\nGuarulhos serves as the main hub for LATAM Airlines Brazil and GOL Linhas Aéreas, connecting Brazil with destinations across the Americas, Europe, Africa, and the Middle East. São Paulo's economic dominance in South America—the city generates nearly 11% of Brazil's GDP—makes Guarulhos a critical business aviation hub.\n\nThe airport underwent significant upgrades for the 2014 FIFA World Cup, including a new Terminal 3. However, it continues to face operational challenges including traffic congestion on access roads, capacity constraints, and competition with Congonhas for domestic premium traffic. A planned rail link to central São Paulo remains under development." },
  { id: 'apt-jnb', name: 'O.R. Tambo International', type: 'airport', category: 'transport', latitude: -26.1392, longitude: 28.2460, country: 'South Africa', description: "O.R. Tambo International Airport, named after the anti-apartheid leader Oliver Reginald Tambo, is Africa's busiest airport and the primary gateway to southern Africa. Located in Kempton Park, east of Johannesburg, the airport was originally built as Jan Smuts Airport in 1952 and was renamed in 2006.\n\nThe airport handles over 21 million passengers annually and serves as the main hub for South African Airways and several other African carriers. Its strategic position makes it the connecting point for flights between Africa, Europe, Asia, Oceania, and the Americas. O.R. Tambo is the only airport in Africa offering direct flights to all six inhabited continents.\n\nThe airport has invested heavily in security and operational improvements, including an integrated operations center and advanced surveillance systems. Its economic impact on the Gauteng province is substantial, supporting hundreds of thousands of jobs in aviation, logistics, and tourism. Recent challenges include airline financial difficulties and infrastructure aging, with ongoing capital programs addressing terminal modernization and runway rehabilitation." },

  // ===== PORTS =====
  { id: 'port-sha', name: 'Port of Shanghai', type: 'port', category: 'transport', latitude: 31.3604, longitude: 121.6247, country: 'China', description: "The Port of Shanghai is the world's busiest container port by TEU (Twenty-foot Equivalent Unit) volume, handling over 49 million TEUs annually. The port complex encompasses both the older Huangpu River wharves in the city center and the massive Yangshan Deep-Water Port, connected to the mainland by the 32.5-kilometer Donghai Bridge.\n\nYangshan, opened in phases since 2005, represents one of the most ambitious port engineering projects in history, built on a series of small islands in the East China Sea. Phase IV of Yangshan, opened in 2017, is the world's largest automated container terminal, using AI-driven cranes, autonomous guided vehicles, and centralized control systems to handle containers with minimal human intervention.\n\nShanghai's port dominance reflects China's position as the world's manufacturing powerhouse. The port handles a significant portion of China's $3.5 trillion in annual trade, connecting to over 500 ports across the globe. Its strategic importance extends to military logistics, with the People's Liberation Army Navy maintaining facilities in the broader Shanghai maritime area." },
  { id: 'port-sin', name: 'Port of Singapore', type: 'port', category: 'transport', latitude: 1.2644, longitude: 103.8210, country: 'Singapore', description: "The Port of Singapore is the world's second-busiest container port and the premier transshipment hub in Southeast Asia. Located at the southern tip of the Malay Peninsula, at the confluence of the Strait of Malacca, the South China Sea, and the Indian Ocean, Singapore's port has been a critical maritime crossroads for centuries.\n\nModern port operations are managed by PSA International, which operates container terminals at Tanjong Pagar, Keppel, Brani, and Pasir Panjang. The port handles over 37 million TEUs annually and connects to more than 600 ports in 120 countries. Over 130,000 vessels call at Singapore each year, making it one of the world's busiest shipping lanes.\n\nSingapore is developing the Tuas Mega Port, expected to be fully operational by the 2040s, which will consolidate all container operations into a single location with an annual capacity of 65 million TEUs. This project will use fully automated wharf and yard operations. The port's strategic military significance is immense—the Strait of Malacca carries approximately 25% of global maritime trade and is a critical chokepoint for energy shipments from the Middle East to East Asia." },
  { id: 'port-rot', name: 'Port of Rotterdam', type: 'port', category: 'transport', latitude: 51.9036, longitude: 4.4993, country: 'Netherlands', description: "The Port of Rotterdam is Europe's largest seaport and one of the world's most important maritime logistics hubs. Stretching over 42 kilometers from the city center to the North Sea, the port complex includes the Maasvlakte 2 extension, a massive land reclamation project that added 2,000 hectares of new port area.\n\nRotterdam handles over 14 million TEUs of container traffic and approximately 470 million tonnes of total cargo annually, serving as the primary gateway for goods entering the European continent. The port's petrochemical cluster is one of the world's largest, refining and distributing oil, gas, and chemicals throughout Europe.\n\nThe port has positioned itself as a leader in the energy transition, hosting Europe's largest hydrogen import terminal project (Porthos) and carbon capture and storage initiatives. Rotterdam's digital port infrastructure includes AI-powered vessel traffic management and IoT sensors throughout the facility. The port's historical significance dates to the 14th century, and it played a crucial role in the Dutch Republic's Golden Age maritime dominance." },
  { id: 'port-la', name: 'Port of Los Angeles', type: 'port', category: 'transport', latitude: 33.7395, longitude: -118.2613, country: 'United States', description: "The Port of Los Angeles is the busiest container port in the Western Hemisphere and a critical gateway for trans-Pacific trade. Located in San Pedro Bay, the port complex (combined with the adjacent Port of Long Beach) handles nearly 40% of all containerized cargo entering the United States.\n\nThe port processes over 10 million TEUs annually, with the majority of trade flowing between the U.S. and China, Japan, South Korea, and other Asia-Pacific nations. It supports over 3 million jobs across the country and generates approximately $280 billion in annual trade value.\n\nThe port has invested heavily in environmental sustainability, implementing clean air action plans, zero-emission equipment mandates, and shore-to-ship power connections. Recent supply chain disruptions during 2021-2022 highlighted the port's critical role in the U.S. economy, leading to federal investment in infrastructure modernization and 24/7 operations. The port also has strategic military significance as a logistics corridor for the U.S. Pacific Fleet." },
  { id: 'port-hk', name: 'Port of Hong Kong', type: 'port', category: 'transport', latitude: 22.3050, longitude: 114.1689, country: 'China', description: "The Port of Hong Kong has been one of the world's busiest container ports for decades, though it has gradually ceded volume to mainland Chinese competitors like Shanghai and Shenzhen. Located on Victoria Harbour and at Kwai Tsing Container Terminals, the port handles approximately 17 million TEUs annually.\n\nHong Kong's natural deep-water harbour has been a maritime trading center for over 150 years, first developed extensively during the British colonial period. Its free-port status, efficient customs procedures, and strategic location at the mouth of the Pearl River Delta have made it a preferred transshipment hub for southern China trade.\n\nThe port faces increasing competition from nearby Shenzhen's Yantian port and the development of the Greater Bay Area logistics network. However, Hong Kong maintains advantages in legal transparency, financial services integration, and its role as a neutral shipping registry. The port remains important for high-value cargo and serves as a critical connection point between mainland China and international markets." },
  { id: 'port-ham', name: 'Port of Hamburg', type: 'port', category: 'transport', latitude: 53.5364, longitude: 9.9685, country: 'Germany', description: "The Port of Hamburg is Germany's largest port and the third-largest container port in Europe. Known as 'Germany's Gateway to the World,' the port has served as a major trading hub since its founding by Emperor Frederick Barbarossa in 1189, making it one of the oldest port facilities in continuous operation.\n\nSituated on the Elbe River approximately 100 kilometers from the North Sea, Hamburg handles over 8.5 million TEUs annually and serves as the primary maritime logistics hub for Central and Eastern European trade. The port's inland location, connected to an extensive canal, river, rail, and road network, allows efficient distribution throughout the European continent.\n\nHamburg has been at the forefront of smart port technology, deploying IoT sensors, digital twin simulations, and automated stacking cranes. The controversial Elbe River deepening project, completed in 2022, allows larger container vessels to access the port. Hamburg is also developing hydrogen import infrastructure as part of Germany's energy transition strategy." },
  { id: 'port-bus', name: 'Port of Busan', type: 'port', category: 'transport', latitude: 35.0966, longitude: 129.0412, country: 'South Korea', description: "The Port of Busan is South Korea's largest port and one of the world's top five container ports by volume, handling over 22 million TEUs annually. Located at the southeastern tip of the Korean Peninsula, Busan serves as a critical transshipment hub for Northeast Asian trade, connecting trade routes between China, Japan, Russia, and the Americas.\n\nThe port's development accelerated following the Korean War, transforming Busan from a wartime refuge city into a major industrial and logistics center. The New Port complex at Jinhae Bay, operational since 2006, represents one of Asia's most modern container terminal facilities with automated systems and deep-water berths capable of handling the world's largest container vessels.\n\nBusan's strategic significance extends beyond commerce—the port is adjacent to the Republic of Korea Navy's Jinhae Naval Base and has served as a logistics hub for U.S. and allied military forces since the Korean War. The Busan-Jinhae Free Economic Zone integrates port, industrial, and military functions in one of the most strategically important maritime zones in the Pacific." },
  { id: 'port-ant', name: 'Port of Antwerp', type: 'port', category: 'transport', latitude: 51.2930, longitude: 4.3006, country: 'Belgium', description: "The Port of Antwerp-Bruges is Europe's second-largest seaport (following the 2022 merger of the Antwerp and Zeebrugge port authorities). Located on the Scheldt River approximately 80 kilometers from the North Sea, the port has been a major European trading center since the Middle Ages.\n\nAntwerp handles over 14 million TEUs of container traffic and is Europe's largest petrochemical cluster, hosting operations from BASF, ExxonMobil, Total, and other major chemical companies. The port's integrated industrial zone combines maritime logistics with chemical manufacturing, creating one of the most complex industrial ecosystems in the world.\n\nRecent developments include China's COSCO acquiring a stake in a container terminal (a decision that generated significant geopolitical debate in Europe), expansion of the Deurganckdok container terminal, and major investments in hydrogen and carbon capture infrastructure. The port employs over 160,000 people and generates approximately €21 billion in annual added value for the Belgian economy." },
  { id: 'port-jeb', name: 'Jebel Ali Port', type: 'port', category: 'transport', latitude: 25.0075, longitude: 55.0607, country: 'UAE', description: "Jebel Ali Port is the world's largest man-made port and the flagship facility of DP World, one of the world's largest port operators. Located 35 kilometers southwest of Dubai, the port was opened in 1979 and has grown to include over 80 berths with an annual capacity exceeding 22 million TEUs.\n\nThe port serves as the primary maritime gateway for the Middle East and a major transshipment hub connecting East-West trade routes. The adjacent Jebel Ali Free Zone (JAFZA) hosts over 8,000 companies from more than 140 countries, making it one of the world's most successful special economic zones.\n\nJebel Ali's strategic military significance is substantial—it has hosted more U.S. Navy vessels than any port outside the United States and serves as a critical logistics facility for U.S. Central Command operations. The port's deep-water channels can accommodate the world's largest vessels, and its continued expansion reflects Dubai's ambition to remain a global trade hub. Recent investments include automation, green energy initiatives, and expansion of cold chain logistics for food security." },
  { id: 'port-san', name: 'Port of Santos', type: 'port', category: 'transport', latitude: -23.9535, longitude: -46.3126, country: 'Brazil', description: "The Port of Santos is Latin America's largest port and a critical export gateway for Brazilian commodities, particularly soybeans, sugar, coffee, and orange juice. Located on the coast of São Paulo state, Santos has been a major trading port since the 16th century, when it shipped sugar and later coffee to European markets.\n\nThe port handles over 4.5 million TEUs of container traffic and approximately 145 million tonnes of total cargo annually. Its proximity to São Paulo, Brazil's largest industrial center, makes it the natural export point for manufactured goods as well. The port's role in global food security is significant—Brazil is the world's largest exporter of soybeans, sugar, and coffee, and the majority of these exports pass through Santos.\n\nMajor infrastructure challenges include outdated road and rail connections to the port, chronic truck congestion, and environmental concerns related to manganese dust and port expansion into protected coastal ecosystems. A new rail access project and expansion of the Brasil Terminal Portuário are underway to address capacity constraints." },

  // ===== ENERGY: NUCLEAR =====
  { id: 'nuc-bruce', name: 'Bruce Nuclear Station', type: 'nuclear', category: 'energy', latitude: 44.3254, longitude: -81.5972, country: 'Canada', description: "Bruce Nuclear Generating Station is the world's largest operating nuclear power plant by total capacity, producing approximately 6,400 megawatts from eight CANDU pressurized heavy-water reactors. Located on the eastern shore of Lake Huron in Ontario, Canada, the facility has been operational since 1977 and is operated by Bruce Power under lease from Ontario Power Generation.\n\nThe station consists of two plants (Bruce A and Bruce B), each with four reactors. The CANDU reactor design, unique to Canada, uses natural uranium fuel and heavy water as both moderator and coolant, allowing online refueling without shutting down the reactor. Bruce Power provides approximately 30% of Ontario's electricity, making it one of the most critical energy infrastructure assets in North America.\n\nA major life-extension program is currently underway to refurbish all eight reactors, extending their operational life to the 2060s at a cost of approximately $13 billion. The Bruce site is also being evaluated for small modular reactor (SMR) deployment and medical isotope production, particularly for cancer-fighting treatments. The facility's security is managed in coordination with the RCMP and Canadian Armed Forces." },
  { id: 'nuc-kashiwazaki', name: 'Kashiwazaki-Kariwa', type: 'nuclear', category: 'energy', latitude: 37.4289, longitude: 138.5965, country: 'Japan', description: "Kashiwazaki-Kariwa Nuclear Power Plant is the world's largest nuclear power plant by net capacity (7,965 MW), located on the coast of Niigata Prefecture in Japan. Operated by Tokyo Electric Power Company (TEPCO), the facility houses seven reactors: five boiling water reactors (BWR) and two advanced boiling water reactors (ABWR).\n\nThe plant has been shut down since the 2011 Fukushima Daiichi disaster, which TEPCO also operated. Restarting Kashiwazaki-Kariwa has been a politically contentious issue in Japan, as it requires approval from the Nuclear Regulation Authority, local governments, and public acceptance. The facility's seismic vulnerability was highlighted by the 2007 Chūetsu offshore earthquake, which caused radioactive water leaks and fire damage.\n\nRestarting even a portion of the plant would significantly reduce Japan's dependence on imported fossil fuels and lower electricity costs in the Tokyo metropolitan area. TEPCO has invested over $8 billion in post-Fukushima safety upgrades including tsunami walls, filtered venting systems, and mobile emergency equipment. The plant's future remains uncertain and serves as a litmus test for Japan's broader nuclear energy policy." },
  { id: 'nuc-zaporizhzhia', name: 'Zaporizhzhia Nuclear', type: 'nuclear', category: 'energy', latitude: 47.5076, longitude: 34.5852, country: 'Ukraine', description: "Zaporizhzhia Nuclear Power Plant is Europe's largest nuclear power station, featuring six VVER-1000 pressurized water reactors with a total capacity of 5,700 MW. Located in southeastern Ukraine near the city of Enerhodar on the Dnieper River, the plant has been under Russian military control since March 2022, creating an unprecedented nuclear safety crisis.\n\nBefore the conflict, Zaporizhzhia provided approximately 20% of Ukraine's electricity. Since occupation, all six reactors have been shut down, and the plant has been repeatedly disconnected from external power, requiring diesel generators to maintain cooling of spent fuel pools. The International Atomic Energy Agency (IAEA) has maintained a continuous presence at the site since 2022, warning of the danger of a nuclear accident in a war zone.\n\nThe situation at Zaporizhzhia has no precedent in the history of nuclear energy—a major nuclear facility in an active combat zone with shelling damage to auxiliary buildings, disrupted supply lines, and stressed staff. The crisis has prompted global discussions about the vulnerability of nuclear infrastructure in conflict and the need for international protocols protecting nuclear facilities during warfare." },
  { id: 'nuc-gravelines', name: 'Gravelines Nuclear', type: 'nuclear', category: 'energy', latitude: 51.0145, longitude: 2.1074, country: 'France', description: "Gravelines Nuclear Power Station is Western Europe's largest nuclear power plant, with six pressurized water reactors producing a total of 5,460 MW. Located on the English Channel coast in northern France, the plant has been operational since 1980 and is operated by Électricité de France (EDF).\n\nFrance is the world's most nuclear-dependent major economy, with approximately 70% of its electricity generated from nuclear power. Gravelines is a cornerstone of this system, providing base-load power to northern France and contributing to French electricity exports to the UK, Belgium, and other European neighbors.\n\nThe plant's coastal location provides access to seawater for cooling but also raises concerns about rising sea levels and storm surge vulnerability. EDF is conducting major safety upgrades across all French nuclear plants as part of the 'Grand Carénage' life-extension program, estimated to cost over €50 billion nationally. Gravelines is also being evaluated for potential hosting of next-generation EPR2 reactors as France commits to building six to fourteen new nuclear plants." },
  { id: 'nuc-palo', name: 'Palo Verde Nuclear', type: 'nuclear', category: 'energy', latitude: 33.3886, longitude: -112.8615, country: 'United States', description: "Palo Verde Nuclear Generating Station is the largest nuclear power plant in the United States and the only large-scale nuclear facility in the world not situated adjacent to a body of water. Located in the Arizona desert approximately 80 kilometers west of Phoenix, the plant uses treated wastewater from several Phoenix-area municipalities for cooling—an innovative solution that makes it unique among global nuclear facilities.\n\nThe plant consists of three pressurized water reactors with a combined capacity of approximately 3,937 MW, providing base-load electricity to over 4 million people across Arizona, California, New Mexico, and Texas. Palo Verde produces more electricity than any other power plant in the United States, generating approximately 30 billion kilowatt-hours annually.\n\nOperated by Arizona Public Service, the plant has maintained strong safety and generation records. Its desert location provides natural security advantages but also presents challenges including extreme heat, water scarcity, and wildfire risk. The NRC has granted license extensions allowing operation through the 2040s, and the plant is considered a critical asset for supporting the rapid growth of data centers and electrification in the American Southwest." },
  { id: 'nuc-hanul', name: 'Hanul Nuclear', type: 'nuclear', category: 'energy', latitude: 37.0929, longitude: 129.3830, country: 'South Korea', description: "Hanul Nuclear Power Plant (formerly Ulchin) is a major South Korean nuclear complex on the east coast of Gyeongsang Province, featuring six pressurized water reactors with a total capacity of approximately 5,900 MW. The site includes both older Korean Standard Nuclear Power Plant (KSNP) units and newer APR-1400 advanced reactors.\n\nSouth Korea is one of the world's most nuclear-dependent nations, with nuclear power providing approximately 30% of the country's electricity. The Hanul complex is one of four major nuclear sites operated by Korea Hydro & Nuclear Power (KHNP), which has also become a major nuclear technology exporter, winning contracts to build APR-1400 reactors in the UAE.\n\nThe facility's coastal location on the Sea of Japan (East Sea) raises strategic considerations given its proximity to North Korea and the potential vulnerability to missile attack. South Korea maintains robust nuclear security protocols, and the plant is included in national defense planning. Two additional APR-1400 units (Shin-Hanul 1 and 2) have been under construction at an adjacent site." },
  { id: 'nuc-hinkley', name: 'Hinkley Point C', type: 'nuclear', category: 'energy', latitude: 51.2080, longitude: -3.1310, country: 'United Kingdom', description: "Hinkley Point C is a nuclear power station under construction in Somerset, England, representing the United Kingdom's first new nuclear power plant in over two decades. When completed, it will feature two European Pressurized Reactors (EPR) with a combined capacity of 3,260 MW, capable of supplying approximately 7% of the UK's electricity needs.\n\nThe project, led by EDF Energy with significant Chinese investment through CGN, has been one of Europe's most complex and controversial energy infrastructure projects. Originally estimated at £18 billion, costs have escalated to over £33 billion, with completion delayed to 2029-2031. The construction workforce has exceeded 10,000, making it one of the largest construction sites in Europe.\n\nHinkley Point C is central to the UK's strategy for achieving net-zero carbon emissions by 2050, providing reliable low-carbon base-load power. The Somerset coast already hosts two earlier Hinkley Point stations (A, now decommissioning, and B, still operating). The project has driven significant investment in UK nuclear skills, with a new National College for Nuclear and thousands of apprenticeships created." },
  { id: 'nuc-barakah', name: 'Barakah Nuclear', type: 'nuclear', category: 'energy', latitude: 23.9681, longitude: 52.2571, country: 'UAE', description: "Barakah Nuclear Energy Plant is the first nuclear power plant in the Arab world, located in the Al Dhafra region of Abu Dhabi emirate. The facility consists of four APR-1400 reactors built by the Korea Electric Power Corporation (KEPCO), with a total capacity of 5,600 MW. The first unit began commercial operations in 2021, with subsequent units following in sequence.\n\nBarakah represents a landmark achievement in the UAE's energy diversification strategy, reducing dependence on natural gas for electricity generation. At full operation, the four units will provide approximately 25% of the UAE's electricity needs and prevent 22 million tonnes of carbon emissions annually, equivalent to removing 3.2 million cars from the road.\n\nThe project has been notable for its relatively smooth construction timeline compared to other nuclear projects globally, benefiting from South Korean construction expertise and UAE project management. The plant is operated by Nawah Energy Company, a joint venture between Emirates Nuclear Energy Corporation (ENEC) and KEPCO. Security at the facility is extensive, given the geopolitically sensitive Persian Gulf location, with coordination between UAE Armed Forces and international nuclear security agencies." },

  // ===== ENERGY: HYDRO =====
  { id: 'hydro-tgd', name: 'Three Gorges Dam', type: 'hydro', category: 'energy', latitude: 30.8231, longitude: 111.0034, country: 'China', description: "The Three Gorges Dam is the world's largest hydroelectric power station by installed capacity, generating 22,500 MW from 32 main turbines plus two smaller generators. Located on the Yangtze River in Hubei Province, the dam was completed in 2006 after nearly two decades of construction, representing the most ambitious hydraulic engineering project in history.\n\nThe dam serves three primary purposes: flood control for the densely populated Yangtze River basin, navigation improvement for river shipping, and clean electricity generation. It produces approximately 100 TWh of electricity annually, equivalent to burning 50 million tonnes of coal, and has prevented an estimated $100 billion in flood damages since completion.\n\nHowever, the Three Gorges Dam remains deeply controversial. Its construction required the relocation of over 1.3 million people and submerged 13 cities, 140 towns, and 1,350 villages. Environmental impacts include disruption of fish migration, sediment trapping, increased seismic risk, and water quality degradation. Geopolitically, the dam is considered a critical national security asset—its failure would catastrophically flood cities downstream including Wuhan (population 11 million), and it is reportedly among the most heavily defended military installations in China." },
  { id: 'hydro-itaipu', name: 'Itaipu Dam', type: 'hydro', category: 'energy', latitude: -25.4084, longitude: -54.5894, country: 'Brazil/Paraguay', description: "The Itaipu Dam is a binational hydroelectric dam on the Paraná River, operated jointly by Brazil and Paraguay. With an installed capacity of 14,000 MW from 20 generating units, Itaipu held the record as the world's largest hydroelectric facility until the completion of China's Three Gorges Dam. However, Itaipu still frequently generates more electricity annually due to its higher capacity factor.\n\nThe dam is an engineering marvel, stretching 7,919 meters across the Paraná River. Its construction between 1975 and 1984 was one of the largest civil engineering projects ever undertaken, requiring the diversion of the world's seventh-largest river and the excavation of 50 million tonnes of earth and rock.\n\nItaipu provides approximately 15% of Brazil's electricity and over 85% of Paraguay's, making it one of the most strategically important energy facilities in South America. The binational management structure, governed by the 1973 Treaty of Itaipu, has been a source of both cooperation and tension between the two countries, particularly regarding electricity pricing. The dam's reservoir created a massive artificial lake that submerged the spectacular Guaíra Falls, once the world's largest waterfall by volume." },
  { id: 'hydro-guri', name: 'Guri Dam', type: 'hydro', category: 'energy', latitude: 7.7597, longitude: -63.0023, country: 'Venezuela', description: "Guri Dam (officially the Simón Bolívar Hydroelectric Plant) is one of the world's largest hydroelectric facilities, with an installed capacity of 10,235 MW. Located on the Caroní River in Bolívar State, southeastern Venezuela, the dam was completed in two phases (1978 and 1986) and provides approximately 73% of Venezuela's electricity.\n\nVenezuela's extreme dependence on Guri has been a critical vulnerability, dramatically illustrated during the severe droughts of 2009-2010 and 2015-2016 when falling reservoir levels led to nationwide electricity rationing and economic disruption. The March 2019 national blackout, attributed to a combination of equipment failure and years of maintenance neglect, left the entire country without power for days.\n\nThe dam's deterioration mirrors Venezuela's broader infrastructure crisis. Under-investment, loss of skilled personnel due to emigration, and political instability have compromised maintenance and operations. Despite its critical importance, the facility suffers from corroded turbines, unreliable transmission lines, and inadequate vegetation management around the reservoir. The Caroní River basin, which feeds Guri, is also threatened by illegal gold mining activities causing deforestation and water contamination." },
  { id: 'hydro-tucurui', name: 'Tucuruí Dam', type: 'hydro', category: 'energy', latitude: -3.8317, longitude: -49.6461, country: 'Brazil', description: "Tucuruí Dam is a major hydroelectric facility on the Tocantins River in Pará State, Brazilian Amazonia, with an installed capacity of 8,370 MW. Completed in 1984, it was the first large dam built in the Brazilian Amazon rainforest and remains one of the largest in the world.\n\nThe dam was originally constructed to supply electricity to aluminum smelting operations in the Amazon, particularly the Albrás-Alunorte complex, and to connect the isolated northern grid to the national system. Its reservoir covers 2,850 square kilometers, making it one of the largest artificial lakes in the Amazon basin.\n\nTucuruí's construction was highly controversial due to its environmental and social impacts. The reservoir flooded extensive areas of tropical forest, displacing indigenous communities and creating vast areas of decomposing vegetation that produced methane emissions, partially offsetting the dam's climate benefits. Malaria rates in the region increased dramatically after reservoir creation. Despite these costs, the dam provides critical clean energy for northern Brazil and has enabled industrial development in a historically isolated region." },
  { id: 'hydro-grand-coulee', name: 'Grand Coulee Dam', type: 'hydro', category: 'energy', latitude: 47.9558, longitude: -118.9817, country: 'United States', description: "Grand Coulee Dam is the largest hydroelectric facility in the United States and one of the largest concrete structures ever built. Located on the Columbia River in Washington State, the dam was constructed between 1933 and 1942 as part of President Franklin Roosevelt's New Deal, with additional powerhouses added through the 1970s.\n\nThe dam's 6,809 MW capacity generates approximately 21 billion kilowatt-hours annually, enough to power over 2 million homes. Beyond power generation, Grand Coulee irrigates over 670,000 acres of farmland in the Columbia Basin through a system of canals, pumping stations, and reservoirs that transformed arid scrubland into one of America's most productive agricultural regions.\n\nThe dam's construction fundamentally altered the Columbia River ecosystem, blocking salmon migration to over 1,100 miles of spawning habitat upstream. This devastated the fishing-based economies and cultures of Native American tribes, particularly the Colville and Spokane peoples, whose traditional fishing sites were submerged. Modern debates over dam removal on the lower Snake River connect to Grand Coulee's legacy of trading ecological health for economic development." },
  { id: 'hydro-aswan', name: 'Aswan High Dam', type: 'hydro', category: 'energy', latitude: 23.9708, longitude: 32.8781, country: 'Egypt', description: "The Aswan High Dam is one of the most significant engineering projects of the 20th century, built across the Nile River at Aswan in southern Egypt. Completed in 1970 with Soviet financial and technical assistance, the dam created Lake Nasser, one of the world's largest artificial lakes, stretching 550 kilometers into Sudan.\n\nThe dam generates approximately 2,100 MW of electricity, which at completion provided over half of Egypt's power supply. More importantly, it ended the Nile's millennia-old annual flood cycle, allowing year-round irrigation and enabling Egypt to expand its agricultural land by over 30%. The dam provides water storage critical to Egypt's food security for its population of over 100 million people.\n\nThe dam's construction required the relocation of the Abu Simbel temples and other Nubian monuments in an unprecedented international archaeological rescue operation led by UNESCO. However, the dam has also caused significant environmental changes: the Nile delta is eroding due to trapped sediment, downstream soil fertility has decreased requiring chemical fertilizers, and sardine fisheries in the eastern Mediterranean have collapsed. The dam remains one of Egypt's most strategically sensitive facilities—its catastrophic failure would devastate virtually all of Egypt's population and infrastructure." },

  // ===== ENERGY: WIND FARMS =====
  { id: 'wind-gansu', name: 'Gansu Wind Farm', type: 'wind_farm', category: 'energy', latitude: 40.3106, longitude: 96.6332, country: 'China', description: "The Gansu Wind Farm (also known as the Jiuquan Wind Power Base) is the world's largest wind farm complex, located in the Gobi Desert region of Gansu Province, northwestern China. When fully completed, the facility is planned to reach 20,000 MW of installed capacity, making it one of the most ambitious renewable energy projects ever undertaken.\n\nThe project is part of China's broader strategy to develop massive wind power bases in its resource-rich but sparsely populated western regions. Construction began in 2009, and the facility has been expanded in multiple phases. The desert location provides consistent strong winds but also presents challenges including sandstorm damage to turbine blades and extreme temperature variations.\n\nA major challenge has been the transmission of electricity from remote Gansu to the demand centers in eastern China, requiring ultra-high-voltage direct current (UHVDC) transmission lines spanning thousands of kilometers. Significant curtailment (wasted wind energy) has occurred due to grid integration difficulties. Despite these challenges, the Gansu Wind Farm represents China's commitment to leading global renewable energy deployment and reducing its dependence on coal-fired power generation." },
  { id: 'wind-hornsea', name: 'Hornsea Wind Farm', type: 'wind_farm', category: 'energy', latitude: 53.8850, longitude: 1.7800, country: 'United Kingdom', description: "The Hornsea Wind Farm complex is the world's largest offshore wind farm, located in the North Sea approximately 120 kilometers off the Yorkshire coast of England. Developed by Ørsted, the Danish energy company, the complex consists of multiple phases: Hornsea One (1,218 MW, operational since 2020) and Hornsea Two (1,386 MW, operational since 2022), with Hornsea Three (2,852 MW) under development.\n\nHornsea One was a landmark project, demonstrating that offshore wind farms could be built at utility scale far from shore, where wind resources are stronger and more consistent. The project uses Siemens Gamesa 7 MW turbines, with foundations driven into the seabed in water depths of 25-35 meters.\n\nThe UK has the world's most developed offshore wind industry, with Hornsea as its flagship project. The government's target of 50 GW of offshore wind by 2030 positions these North Sea developments as central to UK energy security and climate strategy. The projects have created thousands of manufacturing and construction jobs in economically deprived coastal communities, and the Humber region has become a global hub for offshore wind supply chain activity." },
  { id: 'wind-alta', name: 'Alta Wind Energy Center', type: 'wind_farm', category: 'energy', latitude: 35.0637, longitude: -118.3655, country: 'United States', description: "The Alta Wind Energy Center is the largest onshore wind farm in the United States, located in Tehachapi, California, in the Tehachapi Pass—one of the windiest locations in the state. The facility has an installed capacity of approximately 1,548 MW across multiple phases, using over 600 wind turbines.\n\nTehachapi Pass has been a center of wind energy development since the 1980s, when California's early renewable energy incentives sparked the first wind rush. The Alta project, developed from 2010-2014, replaced many older, less efficient turbines with modern machines that produce significantly more power per unit.\n\nThe wind farm's electricity is transmitted to the Los Angeles area via Southern California Edison's Tehachapi Renewable Transmission Project, a $2.5 billion investment in high-voltage transmission lines through the mountains. The Alta facility generates enough clean electricity to power over 450,000 homes and displaces approximately 3 million tonnes of CO2 annually compared to natural gas generation." },
  { id: 'wind-jaisalmer', name: 'Jaisalmer Wind Park', type: 'wind_farm', category: 'energy', latitude: 26.9157, longitude: 70.9083, country: 'India', description: "The Jaisalmer Wind Park is one of India's largest wind energy installations, located in the Thar Desert region of Rajasthan. With an installed capacity exceeding 1,600 MW, the facility takes advantage of the consistent desert winds that sweep across the arid landscape of western India.\n\nIndia is the fourth-largest wind energy producer globally, and Rajasthan's desert regions have emerged as prime locations for wind power development due to their strong wind resources, available land, and low population density. Multiple developers including Suzlon, Enercon, and Vestas have installed turbines across the Jaisalmer district.\n\nThe wind park contributes significantly to India's ambitious renewable energy targets—the government aims for 500 GW of non-fossil fuel capacity by 2030. Challenges include grid integration, land acquisition disputes with local communities, and the desert environment's impact on equipment maintenance. The facility also plays a role in India's energy security strategy, reducing dependence on imported fossil fuels and providing domestic energy resilience." },
  { id: 'wind-dogger', name: 'Dogger Bank Wind Farm', type: 'wind_farm', category: 'energy', latitude: 54.7500, longitude: 2.0000, country: 'United Kingdom', description: "Dogger Bank Wind Farm, currently under construction in the North Sea, will be the world's largest offshore wind farm upon completion with a total capacity of 3,600 MW across three phases (A, B, and C). The project is a joint venture between SSE Renewables, Equinor, and Eni, located on the Dogger Bank sandbank approximately 130 kilometers off the northeast coast of England.\n\nThe project will use GE Renewable Energy's Haliade-X turbines, among the world's most powerful at 13-14.7 MW each—a single rotation of one blade can power a UK household for over two days. Dogger Bank A began producing power in 2023, with all three phases expected to be fully operational by 2026.\n\nThe Dogger Bank project represents a quantum leap in offshore wind technology, demonstrating that massive wind farms can operate efficiently far from shore in challenging North Sea conditions. The project will provide enough clean electricity to power over 6 million UK homes and is central to the UK's strategy for energy independence and net-zero emissions. The shallow waters of the Dogger Bank (15-36 meters depth) provide favorable foundation conditions, though the area's importance as a fishing ground has raised environmental and economic concerns." },

  // ===== ENERGY: SOLAR FARMS =====
  { id: 'solar-bhadla', name: 'Bhadla Solar Park', type: 'solar_farm', category: 'energy', latitude: 27.5297, longitude: 71.9125, country: 'India', description: "Bhadla Solar Park is the world's largest solar park, spanning approximately 5,700 hectares in the Thar Desert of Rajasthan, India. With an installed capacity of 2,245 MW, the park has been developed in phases by multiple companies including Adani Green Energy, SB Energy (SoftBank), and other developers under the direction of Rajasthan Solar Park Development Company.\n\nThe park's location in the Thar Desert provides exceptional solar irradiance, with over 300 sunny days per year and some of the highest solar energy potential in the world. Temperatures in the region can exceed 48°C, requiring specially designed panels and cooling systems that maintain efficiency in extreme heat.\n\nBhadla is a cornerstone of India's National Solar Mission and its broader commitment to achieving 500 GW of renewable energy capacity by 2030. The park has achieved some of the lowest solar electricity tariffs in the world, demonstrating that solar power can be cheaper than coal in India. The project has transformed a barren desert region, creating thousands of construction and maintenance jobs, though it has also raised questions about land rights and the impact on traditional pastoral communities." },
  { id: 'solar-tengger', name: 'Tengger Desert Solar', type: 'solar_farm', category: 'energy', latitude: 37.4370, longitude: 104.8074, country: 'China', description: "The Tengger Desert Solar Park, located in the Tengger Desert of Ningxia Province, China, is one of the world's largest solar installations with an installed capacity exceeding 1,500 MW. The facility covers approximately 43 square kilometers of desert terrain, earning it the nickname 'The Great Wall of Solar' when viewed from satellite imagery.\n\nThe project is part of China's massive investment in renewable energy infrastructure in its western provinces, leveraging abundant desert land and solar resources to generate clean electricity for transmission to population centers in eastern China. The facility uses both crystalline silicon photovoltaic panels and some concentrating solar power technology.\n\nChina's dominance in solar manufacturing and deployment is evident at Tengger—the panels are primarily produced domestically, and Chinese engineering firms manage construction and operations. The desert environment minimizes land-use conflicts but presents challenges including sandstorm damage, panel soiling, and extreme temperature cycling. The Tengger facility contributes to China's position as the world's largest solar energy producer, with over 400 GW of installed solar capacity nationally." },
  { id: 'solar-noor', name: 'Noor-Ouarzazate', type: 'solar_farm', category: 'energy', latitude: 31.0370, longitude: -6.8610, country: 'Morocco', description: "The Noor-Ouarzazate Solar Complex is the world's largest concentrated solar power (CSP) plant, located near the city of Ouarzazate in southern Morocco on the edge of the Sahara Desert. The complex spans over 3,000 hectares and combines multiple solar technologies with a total capacity exceeding 580 MW.\n\nNoor I uses parabolic trough technology with molten salt thermal storage, allowing electricity generation for up to three hours after sunset. Noor II also uses parabolic troughs, while Noor III features a 243-meter solar tower—one of the tallest in the world—surrounded by thousands of heliostats that concentrate sunlight onto a central receiver. Noor IV uses conventional photovoltaic technology.\n\nThe project is a flagship of Morocco's ambitious renewable energy strategy, which aims to derive 52% of electricity from renewables by 2030. Funded by international development banks including the World Bank and African Development Bank, Noor-Ouarzazate has positioned Morocco as a renewable energy leader in Africa and the Middle East. The complex is expected to reduce Morocco's carbon emissions by 760,000 tonnes annually and serve as a potential export platform for clean energy to Europe via submarine cables across the Strait of Gibraltar." },
  { id: 'solar-topaz', name: 'Topaz Solar Farm', type: 'solar_farm', category: 'energy', latitude: 35.0380, longitude: -119.9590, country: 'United States', description: "Topaz Solar Farm is one of the largest photovoltaic power stations in the United States, with an installed capacity of 580 MW. Located on 19 square kilometers of former ranchland in the Carrizo Plain of San Luis Obispo County, California, the project was developed by First Solar and completed in 2014.\n\nThe facility uses approximately 9 million First Solar thin-film cadmium telluride (CdTe) panels, which perform better than traditional silicon panels in the high temperatures common in the Carrizo Plain. The project provides enough clean electricity to power approximately 180,000 California homes.\n\nTopaz was one of the first utility-scale solar projects to demonstrate that photovoltaic farms could be built quickly and cost-effectively on agricultural land. The Carrizo Plain location was selected for its exceptional solar resource and flat terrain, though the area is also home to endangered species including the San Joaquin kit fox and giant kangaroo rat, requiring extensive environmental mitigation. The project was purchased by Berkshire Hathaway Energy for approximately $2.5 billion, signaling major corporate investment in solar energy." },
  { id: 'solar-benban', name: 'Benban Solar Park', type: 'solar_farm', category: 'energy', latitude: 24.4550, longitude: 32.7420, country: 'Egypt', description: "Benban Solar Park is Africa's largest solar installation and one of the largest in the world, located near the city of Aswan in Upper Egypt. The park spans approximately 37 square kilometers and has an installed capacity of 1,650 MW from 41 individual solar plants developed by various international companies.\n\nThe project was developed under Egypt's Feed-in Tariff program with support from the European Bank for Reconstruction and Development (EBRD), the International Finance Corporation (IFC), and other international lenders. The desert location near Aswan provides exceptional solar irradiance—among the highest in the world—with over 3,500 hours of sunshine annually.\n\nBenban has been transformative for Egypt's energy sector, reducing dependence on natural gas for electricity generation and creating over 10,000 construction jobs during development. The park's proximity to the Aswan High Dam creates an interesting energy corridor, with both hydroelectric and solar resources concentrated in the same region. Egypt aims to derive 42% of its electricity from renewable sources by 2035, with Benban as its most visible achievement." },

  // ===== TELECOM =====
  { id: 'twr-tokyo', name: 'Tokyo Skytree', type: 'broadcast_tower', category: 'telecom', latitude: 35.7101, longitude: 139.8107, country: 'Japan', description: "Tokyo Skytree is the world's tallest tower at 634 meters and serves as the primary broadcast antenna for the Tokyo metropolitan area. Completed in 2012 in the Sumida ward, the tower replaced Tokyo Tower as the city's main digital terrestrial television broadcasting facility, addressing signal reception issues caused by Tokyo's increasingly dense skyline of high-rise buildings.\n\nThe tower's design draws from traditional Japanese aesthetics, incorporating a subtle curvature that transitions from a triangular base to a circular cross-section. Its structural engineering is remarkable, featuring a central concrete shaft with a steel frame and a tuned mass damper system designed to withstand earthquakes of magnitude 7+ and typhoon-force winds.\n\nBeyond broadcasting, Tokyo Skytree serves as a major tourist attraction with two observation decks at 350m and 450m, attracting over 30 million visitors since opening. The tower broadcasts signals for NHK, Nippon Television, and other major Japanese networks. It also supports mobile telecommunications, emergency broadcasting systems, and serves as a critical node in Japan's disaster communication infrastructure—particularly important given the country's seismic vulnerability." },
  { id: 'twr-cn', name: 'CN Tower', type: 'broadcast_tower', category: 'telecom', latitude: 43.6426, longitude: -79.3871, country: 'Canada', description: "The CN Tower is a 553-meter communications and observation tower in downtown Toronto, Ontario. Completed in 1976, it held the record as the world's tallest free-standing structure for over 30 years. The tower was originally built by Canadian National Railway (CN) to serve as a telecommunications hub, addressing poor reception caused by Toronto's growing cluster of skyscrapers.\n\nThe tower carries over 30 broadcast antenna systems serving television stations, FM radio stations, and wireless telecommunications providers for the Greater Toronto Area. Its geographic elevation and height make it one of the most important broadcast transmission points in North America, serving a metropolitan area of over 6 million people.\n\nBeyond its technical role, the CN Tower is Canada's most iconic architectural landmark and a major tourist destination, attracting approximately 1.5 million visitors annually. Features include the world-famous EdgeWalk (a hands-free walk on a 1.5-meter-wide ledge around the tower's exterior at 356m), a glass floor observation level, and the 360 Restaurant. The tower has been designated as one of the Seven Wonders of the Modern World by the American Society of Civil Engineers." },
  { id: 'twr-shanghai', name: 'Oriental Pearl Tower', type: 'broadcast_tower', category: 'telecom', latitude: 31.2397, longitude: 121.4998, country: 'China', description: "The Oriental Pearl Radio & Television Tower is a 468-meter broadcast tower located in the Pudong district of Shanghai, China. Completed in 1994, it was the tallest structure in China at the time of completion and served as the primary broadcast antenna for Shanghai's television and radio stations.\n\nThe tower's distinctive design features eleven spheres of varying sizes connected by three main columns, creating a silhouette that evokes traditional Chinese aesthetics of 'twin dragons playing with pearls.' The largest sphere, at 50 meters in diameter, houses a revolving restaurant, while the upper sphere contains an observation deck offering panoramic views of the Bund, Huangpu River, and Pudong skyline.\n\nWhile no longer Shanghai's tallest structure (surpassed by the Shanghai Tower at 632 meters), the Oriental Pearl Tower remains one of the city's most recognizable landmarks and continues to serve critical telecommunications functions. It broadcasts signals for Shanghai Media Group and other local stations, and supports 4G/5G telecommunications infrastructure. The tower's base houses the Shanghai History Museum, one of the city's most visited cultural institutions." },
  { id: 'twr-berlin', name: 'Berliner Fernsehturm', type: 'broadcast_tower', category: 'telecom', latitude: 52.5208, longitude: 13.4094, country: 'Germany', description: "The Berliner Fernsehturm (Berlin Television Tower) is a 368-meter tower at Alexanderplatz in central Berlin, making it the tallest structure in Germany. Constructed by the German Democratic Republic between 1965 and 1969, the tower was intended as a symbol of Communist East Germany's technological prowess and is now one of unified Berlin's most prominent landmarks.\n\nThe tower serves as a major broadcast transmission facility for Berlin and Brandenburg, carrying television, FM radio, and mobile telecommunications signals. Its distinctive sphere, located at 204 meters, houses a revolving restaurant and observation deck that attracts over 1.2 million visitors annually.\n\nThe Fernsehturm's Cold War history is integral to its identity—it was designed to be visible from West Berlin as a demonstration of socialist achievement, though West Berliners noted that sunlight reflecting off the sphere created a cross shape (nicknamed the 'Pope's Revenge'), an ironic symbol for an atheist state. After German reunification, the tower was modernized and has remained an essential part of Berlin's telecommunications infrastructure while becoming one of Europe's most visited tourist attractions." },
  { id: 'twr-ostankino', name: 'Ostankino Tower', type: 'broadcast_tower', category: 'telecom', latitude: 55.8197, longitude: 37.6117, country: 'Russia', description: "Ostankino Tower is a 540-meter television and radio tower in Moscow, currently the tallest free-standing structure in Europe. Completed in 1967, it was built to serve as the central broadcasting facility for Soviet television, replacing an earlier, smaller transmission tower that could not serve Moscow's rapidly expanding metropolitan area.\n\nThe tower broadcasts signals for major Russian television networks including Channel One, Russia-1, NTV, and numerous radio stations. Its height and central Moscow location provide coverage extending approximately 120 kilometers in all directions. The tower also supports military and government communications systems.\n\nOstankino suffered a devastating fire in August 2000 that killed three people, destroyed the observation deck and restaurant, and briefly knocked out television broadcasting for millions of Moscow residents. The fire exposed the vulnerability of centralized broadcasting infrastructure and led to significant investment in redundant transmission systems. Restoration was completed in 2008. The tower remains a symbol of Russian engineering achievement and serves as a critical node in the country's national telecommunications architecture." },
  { id: 'twr-kl', name: 'KL Tower', type: 'broadcast_tower', category: 'telecom', latitude: 3.1529, longitude: 101.7007, country: 'Malaysia', description: "Menara Kuala Lumpur (KL Tower) is a 421-meter telecommunications tower located on Bukit Nanas hill in central Kuala Lumpur. Completed in 1995, the tower serves as the primary broadcast transmission facility for Malaysian television and radio stations, and supports extensive mobile telecommunications infrastructure.\n\nThe tower's design incorporates Islamic architectural elements, with the main shaft featuring a pattern inspired by traditional Malay weaving and the antenna platform resembling a muqarnas (honeycomb vault) found in mosques. Its hilltop location gives it an effective height advantage, making it visible from most parts of the Kuala Lumpur metropolitan area.\n\nKL Tower serves as a critical node in Malaysia's telecommunications network, supporting broadcasts for RTM, TV3, and other major Malaysian broadcasters, as well as 4G/5G mobile services. The tower includes an observation deck, revolving restaurant, and a base area that preserves one of the oldest remaining patches of tropical rainforest in Kuala Lumpur—the Bukit Nanas Forest Reserve. During annual celebrations, the tower hosts the International Tower Jump, attracting BASE jumpers from around the world." },
  { id: 'twr-cairo', name: 'Cairo Tower', type: 'broadcast_tower', category: 'telecom', latitude: 30.0459, longitude: 31.2243, country: 'Egypt', description: "Cairo Tower is a 187-meter concrete tower on Gezira Island in the Nile River, completed in 1961. While modest in height compared to modern telecommunications towers, it remains one of the most distinctive structures in Cairo and the tallest in North Africa. The tower's latticed design is inspired by the lotus plant, an ancient Egyptian symbol.\n\nThe tower serves as a local broadcasting and telecommunications facility, supporting transmission of Egyptian radio and television signals across the Cairo metropolitan area. Its elevated position on Gezira Island, combined with the generally flat terrain of the Nile Delta, provides effective coverage of the densely populated capital region.\n\nHistorically, the tower has an intriguing origin—according to popular accounts, it was funded using a $3 million CIA payment to Egyptian President Gamal Abdel Nasser, who reportedly used the funds for the tower construction as a gesture of defiance rather than the political influence the CIA intended. The tower's revolving restaurant and observation deck offer panoramic views of Cairo, the Pyramids of Giza, and the Nile River, making it one of Egypt's most visited tourist sites." },
  { id: 'twr-sutro', name: 'Sutro Tower', type: 'radio_tower', category: 'telecom', latitude: 37.7552, longitude: -122.4528, country: 'United States', description: "Sutro Tower is a 298-meter three-pronged steel antenna tower located on Mount Sutro in San Francisco, California. Completed in 1973, the tower replaced a collection of smaller antenna installations scattered across San Francisco's hills, consolidating broadcast transmission for the entire Bay Area into a single facility.\n\nThe tower carries broadcast antennas for virtually all major television and FM radio stations serving the San Francisco-Oakland-San Jose metropolitan area, one of the largest media markets in the United States. Its distinctive triple-forked design, often visible above the fog that blankets San Francisco, has made it one of the city's most recognizable landmarks.\n\nSutro Tower's role has evolved with the transition from analog to digital broadcasting, and it now also supports cellular telecommunications, emergency services communications, and data transmission. The tower has been controversial since its construction, with some residents considering it an eyesore, while others have embraced it as an iconic part of San Francisco's skyline. Its position on one of the highest points in the city provides line-of-sight coverage to virtually the entire Bay Area." },
  { id: 'twr-kvly', name: 'KVLY-TV Mast', type: 'radio_tower', category: 'telecom', latitude: 47.3442, longitude: -97.2886, country: 'United States', description: "The KVLY-TV Mast is a 628.8-meter (2,063-foot) guyed television mast near Blanchard, North Dakota, making it one of the tallest structures in the Western Hemisphere. Completed in 1963, the mast was built to serve KVLY-TV (then KXJB-TV), providing television coverage across the flat terrain of the northern Great Plains.\n\nThe mast's extreme height is necessary due to the vast, flat geography of North Dakota—without significant elevation, a tall structure is required to achieve line-of-sight coverage over hundreds of kilometers of prairie. The mast broadcasts signals for CBS-affiliated KVLY-TV to communities across eastern North Dakota and western Minnesota.\n\nGuyed masts like KVLY are among the tallest human-made structures but are relatively lightweight and inexpensive compared to free-standing towers. The structure is supported by multiple sets of guy wires anchored to the ground at distances of up to 500 meters from the base. Winter ice accumulation on the mast and cables is a significant maintenance challenge, and the structure has red aviation warning lights visible for dozens of kilometers across the flat landscape." },
  { id: 'twr-lualualei', name: 'Lualualei VLF Station', type: 'radio_tower', category: 'telecom', latitude: 21.4217, longitude: -158.1508, country: 'United States', description: "The Naval Computer and Telecommunications Area Master Station Pacific, Lualualei Annex (commonly Lualualei VLF Station) is a Very Low Frequency (VLF) radio transmitter facility operated by the United States Navy in the Lualualei Valley on the island of Oahu, Hawaii.\n\nThe facility features two massive antenna towers—the main tower stands 458 meters tall, making it one of the tallest structures in the world. The VLF transmission capability allows communication with deeply submerged submarines across the Pacific Ocean, as very low frequency radio waves can penetrate seawater to depths that higher-frequency signals cannot reach.\n\nLualualei is a critical component of the U.S. Navy's strategic communications infrastructure, providing the ability to transmit launch orders and other commands to ballistic missile submarines (SSBNs) as part of the United States' nuclear deterrence posture. The facility operates 24/7 and is protected by military security. Its location in Hawaii provides coverage across the vast Pacific theater, complementing similar VLF stations in Cutler, Maine (Atlantic coverage) and Jim Creek, Washington (Pacific Northwest coverage)." },
];
